import { useRef, useState } from "react";
import * as RadioGroup from "@radix-ui/react-radio-group";
import { cn } from "@/lib/cn";

// Base decided in round 2: Radix RadioGroup styled as chips.
// Exactly one chip is always selected. Selecting does not announce: the consumer calls `announce`.

export type FilterChipOption = { value: string; label: string; /** Language of the label, for Indic or mixed scripts. */ lang?: string };

export type FilterChipGroupProps = {
  options: FilterChipOption[];
  value?: string;
  /** Uncontrolled initial value; defaults to the first option ("All"). */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Accessible name of the group (provisional).*/
  label?: string;
  className?: string;
};

const chip = cn(
  "inline-flex min-h-control items-center justify-center rounded-pill border-border-strong bg-surface-raised text-center",
  "font-body text-ui-reading font-regular leading-normal text-text [overflow-wrap:anywhere]",
  "transition-colors duration-fast ease-standard",
  "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring",
  // unselected
  "data-[state=unchecked]:border-bw-default data-[state=unchecked]:px-chip-x data-[state=unchecked]:py-chip-y",
  "data-[state=unchecked]:hover:bg-surface-sunken data-[state=unchecked]:active:border-primary-text data-[state=unchecked]:active:bg-surface-sunken",
  // selected: heavier real border, padding reduced by the difference so the outer size never changes
  "data-[state=checked]:border-bw-heavy data-[state=checked]:border-primary-text data-[state=checked]:bg-primary data-[state=checked]:text-primary-on",
  "data-[state=checked]:px-chip-x-selected data-[state=checked]:py-chip-y-selected data-[state=checked]:font-medium",
  "data-[state=checked]:hover:bg-primary-hover data-[state=checked]:active:bg-primary-active",
);

// The label reserves the width of its heavier weight (hidden medium twin in a pseudo-element),
// so selecting a chip never moves its neighbours.
const label =
  "before:invisible before:block before:h-0 before:overflow-hidden before:font-medium before:content-[attr(data-label)]";

const ARROWS = new Set(["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"]);

export function FilterChipGroup({ options, value, defaultValue, onValueChange, label: groupLabel = "Filter by role", className }: FilterChipGroupProps) {
  const [inner, setInner] = useState(defaultValue ?? options[0]?.value);
  const selected = useRef<string | undefined>(undefined);
  const arrowRecent = useRef(false);
  // A group with fewer than two chips is not rendered (spec section 8).
  if (options.length < 2) return null;
  const known = (v: string | undefined) => options.some((o) => o.value === v);
  if (import.meta.env.DEV && value !== undefined && !known(value)) {
    console.warn(`[FilterChipGroup] value "${value}" is not one of the options; the first option is shown.`);
  }
  const current = known(value ?? inner) ? (value ?? inner) : options[0].value;
  selected.current = current;

  // Single entry point for every selection. It ignores empty values and repeats of the current value,
  // so the group always keeps exactly one selection and one change gives one callback.
  const change = (v: string) => {
    if (!v || v === selected.current) return;
    selected.current = v;
    setInner(v);
    onValueChange?.(v);
  };

  return (
    <RadioGroup.Root
      aria-label={groupLabel}
      value={current}
      onValueChange={change}
      // Radix selects on arrow focus only while the key is still held down, so a fast tap moves focus
      // without selecting. Mark arrow keys here and select on focus within a short window instead.
      onKeyDownCapture={(e) => {
        if (!ARROWS.has(e.key)) return;
        arrowRecent.current = true;
        setTimeout(() => (arrowRecent.current = false), 150);
      }}
      className={cn("flex flex-wrap gap-gap-sm", className)}
    >
      {options.map((o) => (
        <RadioGroup.Item
          key={o.value}
          value={o.value}
          lang={o.lang}
          className={chip}
          onFocus={() => arrowRecent.current && change(o.value)}
        >
          <span data-label={o.label} className={label}>
            {o.label}
          </span>
        </RadioGroup.Item>
      ))}
    </RadioGroup.Root>
  );
}
